package com.alpharip.staffmod.BuildTimelapse.core;
import com.alpharip.staffmod.BuildTimelapse.timeline.*;import java.io.*;import java.util.*;
public final class FileProjectStore implements ProjectStore {private final File root;public FileProjectStore(File r){if(r==null)throw new IllegalArgumentException();root=r;}
public void save(BuildTimelapseProject p,Timeline t)throws IOException{if(!root.exists()&&!root.mkdirs())throw new IOException("Cannot create directory");Properties v=new Properties();v.setProperty("id",p.getId());v.setProperty("name",p.getName());v.setProperty("world",p.getWorld());v.setProperty("created",Long.toString(p.getCreated()));v.setProperty("notes",p.getNotes());File tmp=new File(root,p.getId()+".tmp"),dst=new File(root,p.getId()+".btproj");try(OutputStream o=new FileOutputStream(tmp)){v.store(o,"Build Timelapse");}if(dst.exists()&&!dst.delete())throw new IOException("Cannot replace");if(!tmp.renameTo(dst))throw new IOException("Rename failed");}
public BuildTimelapseProject load(String id)throws IOException{File f=new File(root,id+".btproj");Properties v=new Properties();try(InputStream in=new FileInputStream(f)){v.load(in);}return new BuildTimelapseProject(v.getProperty("id"),v.getProperty("name"),v.getProperty("world"),Long.parseLong(v.getProperty("created")));}}
